Replace flattened inheritance + @ptrCast with idiomatic Zig tagged unions.

## Current (BROKEN)
```zig
pub const Element = struct {
    // All parent fields flattened
    event_listener_list: ...,
    allocator: ...,
    node_type: u16,  // ← Zig reorders this!
    // ...
};

const node: *Node = @ptrCast(&element);  // ❌ BROKEN
```

## New (CORRECT)
```zig
pub const Node = union(enum) {
    element: Element,
    text: Text,
    comment: Comment,
    document: Document,
    // ... all node types

    pub fn nodeType(self: *const Node) u16 {
        return switch (self.*) {
            .element => 1,
            .text => 3,
            .comment => 8,
            // ...
        };
    }

    pub fn asElement(self: *Node) ?*Element {
        return switch (self.*) {
            .element => |*e| e,
            else => null,
        };
    }
};

pub const Element = struct {
    // Own fields only
    allocator: Allocator,
    tag_name: []const u8,
    attributes: List(Attr),
    // ...

    // Parent fields explicitly stored
    parent_node: ?*Node,
    child_nodes: List(*Node),
};
```

