// tests/benchmarks/wrapper_cache_bench.zig

pub fn benchmarkQuerySelectorCacheHit(allocator: std.mem.Allocator) !void {
    // Setup: Create 1000 elements
    var elements: [1000]*runtime.Instance = undefined;
    for (0..1000) |i| {
        elements[i] = createTestElement(allocator, i);
    }

    // Warmup: Query each element once (populate cache)
    for (elements) |elem| {
        _ = try querySelector(elem.id);
    }

    // Benchmark: Query 1000 elements (all cache hits)
    const start = std.time.nanoTimestamp();
    for (0..1000) |i| {
        _ = try querySelector(elements[i].id);
    }
    const duration = std.time.nanoTimestamp() - start;

    const avg_ns = @divTrunc(duration, 1000);
    std.debug.print("Average cache hit: {}ns\n", .{avg_ns});

    // Verify performance: Cache hit should be < 100ns
    try std.testing.expect(avg_ns < 100);
}

pub fn benchmarkQuerySelectorCacheMiss(allocator: std.mem.Allocator) !void {
