Modify wrapInstanceAsV8Object to check cache before creating wrapper and cache new wrappers.

## Objective
Integrate WrapperCache into template_registry.wrapInstanceAsV8Object() to enable wrapper reuse. This is the CRITICAL task that fixes the querySelector identity bug.

## Current Problem
```javascript
const h1 = document.querySelector("header");
const h2 = document.querySelector("header");
console.log(h1 === h2);  // false ❌ (BROKEN)
```

## Expected After This Task
```javascript
const h1 = document.querySelector("header");
const h2 = document.querySelector("header");
console.log(h1 === h2);  // true ✅ (FIXED)
```

## Technical Details

### Changes to wrapInstanceAsV8Object
File: src/runtime/engines/v8/template_registry.zig

```zig
pub fn wrapInstanceAsV8Object(
    instance: *runtime.Instance,
    interface_name: []const u8,
    isolate: *v8.Isolate,
    context: *v8.Context,
) !*v8.Object {
    // ========================================
    // NEW: Check cache first
    // ========================================
    const ctx_mgr = @import("context_manager.zig");
    if (ctx_mgr.getContext(context)) |runtime_ctx| {
        if (runtime_ctx.wrapper_cache) |*cache| {
            if (cache.get(instance)) |cached_wrapper| {
                // Cache hit! Return existing wrapper
                return cached_wrapper;
            }
        }
    }

    // ========================================
    // EXISTING: Create new wrapper (unchanged)
    // ========================================
    const template = getTemplate(interface_name) orelse {
        return error.TemplateNotRegistered;
    };

    const instance_template = v8.v8_FunctionTemplate_InstanceTemplate(template);
    const v8_object = v8.v8_ObjectTemplate_NewInstance(instance_template, context);

    v8.v8_Object_SetAlignedPointerInInternalField(
        v8_object,
        0,
        @ptrCast(instance),
    );

    if (dom_type_info.getTypeInfoByName(interface_name)) |type_info| {
        v8.v8_Object_SetAlignedPointerInInternalField(
            v8_object,
            1,
            @ptrCast(@constCast(type_info)),
        );
    }

    // ========================================
    // NEW: Cache the wrapper
    // ========================================
    if (ctx_mgr.getContext(context)) |runtime_ctx| {
        if (runtime_ctx.wrapper_cache) |*cache| {
            cache.set(instance, v8_object, isolate) catch |err| {
                // Log but don't fail - wrapper is still usable
                std.log.warn("Failed to cache wrapper: {s}", .{@errorName(err)});
            };
        }
    }

    return v8_object;
}
```

