    try cache.set(instance, wrapper1, isolate);

    // Force GC (wrapper1 collected, cache entry removed)
    v8.v8_Isolate_RequestGarbageCollectionForTesting(isolate, v8.GarbageCollectionType.kFullGarbageCollection);
    std.time.sleep(100 * std.time.ns_per_ms);

    // Create new wrapper for same instance (resurrection)
    const wrapper2 = createTestWrapper(isolate, context, instance);
    try cache.set(instance, wrapper2, isolate);

